


/** Read-only invoice history row for timeline rendering and debugging. Detail fields are present only on the activity types their descriptions list. The invoice and the referenced resources remain authoritative for state and money movement. */ export type InvoiceActivityInput = { /** What happened. New values may be added; treat an unrecognized value like `updated`. */ "activity_type": "draft_created" | "issued" | "sent" | "delivery_sent" | "reminder_sent" | "viewed" | "payment_attempt_started" | "payment_applied" | "manual_payment_recorded" | "manual_payment_reversed" | "refund_succeeded" | "voided" | "token_regenerated" | "collection_blocked" | "collection_block_resolved" | "updated" | "marked_uncollectible" | "payment_processing" | "issue_failed" | "overdue" | "reminder_due" | "late_fee_due" | "late_fee_assessed" | "late_fee_waived" | "credited"; /** Merchant ID of the actor, when actor_type is merchant. Some system activities also carry the merchant ID. */ "actor_id"?: string; /** Who performed the activity: the merchant (an API key or dashboard user), the buyer, or Flint on a schedule or in response to a payment event. Absent when no actor was recorded. */ "actor_type"?: "merchant" | "buyer" | "system"; /** Amount of the payment, refund, or late fee. Present on payment_applied, manual_payment_recorded, manual_payment_reversed, refund_succeeded, late_fee_assessed, and late_fee_waived, and on updated when a card refund changed or a credit note refund was requested. */ "amount_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Delivery channel. Present on delivery_sent and reminder_sent. */ "channel"?: "email"; /** Checkout session the buyer paid through. Present on payment_attempt_started for hosted payments. */ "checkout_session_id"?: string; /** Why collection was blocked or unblocked. Present on collection_blocked and collection_block_resolved. */ "collection_block_reason"?: "inventory_unavailable" | "inventory_restored"; /** When the activity happened. Format: date-time. */ "created_at": string | globalThis.Date; /** Total credit applied to the invoice. Present on credited. */ "credit_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Credit note that requested the refund. Present on updated when a credit note refund was requested or changed. */ "credit_note_id"?: string; /** Human-readable Flint description of the activity. */ "description": string; /** Due date that triggered the activity. Present on overdue, reminder_due, and late_fee_due. Format: date-time. */ "due_at"?: string | globalThis.Date; /** Error code of the failed scheduled issue. Present on issue_failed. */ "error_code"?: string; /** Amount the processing payment is expected to settle. Present on payment_processing. */ "expected_amount_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** When the processing payment is expected to settle. Present on payment_processing when known. Format: date-time. */ "expected_settlement_at"?: string | globalThis.Date; /** Flint invoice activity ID. IDs begin with inevt_. */ "invoice_activity_id": string; /** The delivery attempt that sent the email. Present on delivery_sent and reminder_sent. */ "invoice_delivery_attempt_id"?: string; /** The late fee. Present on late_fee_assessed and late_fee_waived. */ "invoice_late_fee_id"?: string; /** The payment attempt. Present on payment_attempt_started and payment_processing. */ "invoice_payment_attempt_id"?: string; /** Schedule entry the activity applies to. Present on overdue, reminder_due, late_fee_due, late_fee_assessed, and late_fee_waived when the invoice has a payment schedule. */ "invoice_schedule_entry_id"?: string; /** Payment intent whose funds were applied. Present on payment_applied. */ "payment_intent_id"?: string; /** Payment rail of the attempt. Present on payment_processing. */ "payment_rail"?: "card" | "ach_debit" | "manual"; /** Related refund. Present on refund_succeeded, and on updated when a card refund changed or a credit note refund was requested or changed. Read the refund for its current status. */ "refund_id"?: string; /** Recipient of the email. Present on delivery_sent and reminder_sent. */ "to_email"?: string; /** Balance written off. Present on marked_uncollectible. */ "written_off_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; };
